-- Migration: 017_create_learning_competencies_table.sql
-- DepEd Three-Term Budget of Work (BOW) for Learning Competencies (Grade 1 to Grade 12)
-- Total Extracted Records: 6406

CREATE TABLE IF NOT EXISTS sc_learning_competencies (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  grade_level_id UUID REFERENCES sc_grade_levels(id) ON DELETE CASCADE,
  learning_area_id UUID REFERENCES sc_learning_areas(id) ON DELETE CASCADE,
  term_id UUID REFERENCES sc_terms(id) ON DELETE CASCADE,
  grade_number INTEGER CHECK (grade_number BETWEEN 1 AND 12),
  learning_area_name TEXT,
  term_name TEXT,
  code TEXT,
  domain_strand TEXT NOT NULL DEFAULT 'General',
  competency_description TEXT NOT NULL,
  target_week TEXT DEFAULT 'Week 1-2',
  target_days INTEGER DEFAULT 5,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Indexes for fast filtering
CREATE INDEX IF NOT EXISTS idx_sc_competencies_grade ON sc_learning_competencies(grade_level_id);
CREATE INDEX IF NOT EXISTS idx_sc_competencies_grade_num ON sc_learning_competencies(grade_number);
CREATE INDEX IF NOT EXISTS idx_sc_competencies_la ON sc_learning_competencies(learning_area_id);
CREATE INDEX IF NOT EXISTS idx_sc_competencies_term ON sc_learning_competencies(term_id);
CREATE INDEX IF NOT EXISTS idx_sc_competencies_active ON sc_learning_competencies(is_active);

-- Enable RLS
ALTER TABLE sc_learning_competencies ENABLE ROW LEVEL SECURITY;

-- RLS Policies
DROP POLICY IF EXISTS "Allow public read access to competencies" ON sc_learning_competencies;
CREATE POLICY "Allow public read access to competencies"
  ON sc_learning_competencies FOR SELECT
  USING (true);

DROP POLICY IF EXISTS "Allow authenticated full access to competencies" ON sc_learning_competencies;
CREATE POLICY "Allow authenticated full access to competencies"
  ON sc_learning_competencies FOR ALL
  TO authenticated
  USING (true)
  WITH CHECK (true);

-- Clear previous data before re-seeding
TRUNCATE TABLE sc_learning_competencies RESTART IDENTITY CASCADE;

