-- Update foreign key references to sc_grade_levels, sc_learning_areas, and sc_terms
UPDATE sc_learning_competencies c
SET grade_level_id = g.id
FROM sc_grade_levels g
WHERE g.grade_number = c.grade_number;

UPDATE sc_learning_competencies c
SET learning_area_id = l.id
FROM sc_learning_areas l
WHERE LOWER(l.name) = LOWER(c.learning_area_name);

UPDATE sc_learning_competencies c
SET term_id = t.id
FROM sc_terms t
WHERE t.name ILIKE '%' || SPLIT_PART(c.term_name, ' ', 1) || '%';
